38	    /// Scan for dotfiles based on the provided list
39	    #[must_use]
40	    pub fn scan_dotfiles(&self, dotfile_names: &[String]) -> Vec<Dotfile> {
41	        let mut found = Vec::new();
42	
43	        for name in dotfile_names {
44	            let path = self.home_dir.join(name);
45	            // Only include if the path actually exists (file or directory)
46	            if path.exists() {
47	                let relative = path
48	                    .strip_prefix(&self.home_dir)
49	                    .unwrap_or(&path)
50	                    .to_path_buf();
51	
52	                // Try to find description from default candidates
53	                let description = crate::dotfile_candidates::find_candidate(name)
54	                    .map(|c| c.description.to_string());
55	
56	                found.push(Dotfile {
57	                    original_path: path.clone(),
58	                    relative_path: relative,
59	                    synced: false,
60	                    description,
61	                    is_common: false,
62	                    is_custom: false,
63	                });
64	            }
65	        }
66	
67	        found
68	    }
