70	    /// Resolve a symlink to its target, following multiple levels if needed
71	    pub fn resolve_symlink(&self, path: &Path) -> Result<PathBuf> {
72	        debug!("Resolving symlink: {:?}", path);
73	        let mut current = path.to_path_buf();
74	        let mut depth = 0;
75	        const MAX_SYMLINK_DEPTH: usize = 20; // Prevent infinite loops
76	
77	        while current.is_symlink() && depth < MAX_SYMLINK_DEPTH {
78	            let target = fs::read_link(&current)
79	                .with_context(|| format!("Failed to read symlink: {current:?}"))?;
80	            debug!("Symlink at depth {}: {:?} -> {:?}", depth, current, target);
81	
82	            // If the symlink is relative, resolve it relative to the parent
83	            if target.is_relative() {
84	                if let Some(parent) = current.parent() {
85	                    current = parent.join(&target);
86	                    debug!("Resolved relative symlink: {:?}", current);
87	                } else {
88	                    current = target;
89	                }
90	            } else {
91	                current = target;
92	            }
93	
94	            depth += 1;
95	        }
96	
97	        if depth >= MAX_SYMLINK_DEPTH {
98	            warn!(
99	                "Symlink depth exceeded (max {}) for: {:?}",
100	                MAX_SYMLINK_DEPTH, path
101	            );
102	            return Err(anyhow::anyhow!("Symlink depth exceeded for: {path:?}"));
103	        }
104	
105	        debug!(
106	            "Resolved symlink: {:?} -> {:?} (depth: {})",
107	            path, current, depth
108	        );
109	        Ok(current)
110	    }
